var period by remember { mutableStateOf({{periods.0.value}}) }
var chosen by remember { mutableStateOf("") }
// A feature value: true is included, false is not included, text is shown as it is.
fun value(v: Any): MonarchPricingFeatureValue =
    when (v) {
        true -> MonarchPricingFeatureValue.Included
        false -> MonarchPricingFeatureValue.NotIncluded
        else -> MonarchPricingFeatureValue.Text(v.toString())
    }

